examples.template:
@OptIn(ExperimentalMonarchApi::class)
MonarchSessionList(
    sessions = sessions,
    footnote = {{footnote}},
    onSignOut = { id ->
        // The app ends the session on its server here.
        sessions = sessions.filterNot { it.id == id }
    },
    onSignOutOthers = { ids -> sessions = sessions.filterNot { it.id in ids } },
    sessionIcon = { MonarchIcon(SampleIcons.Devices, contentDescription = null) },
)

